using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.HighDefinition;
namespace Versus.Remaster.Editor
{
 public static class KazuyaImporter
 {
  [Serializable] class Bone{public string name;public int parent;public Vector3 position,scale;public Quaternion rotation;}
  [Serializable] class Section{public string material;public int[] triangles;}
  [Serializable] class Weight{public int boneIndex0,boneIndex1,boneIndex2,boneIndex3;public float weight0,weight1,weight2,weight3;public BoneWeight Value=>new BoneWeight{boneIndex0=boneIndex0,boneIndex1=boneIndex1,boneIndex2=boneIndex2,boneIndex3=boneIndex3,weight0=weight0,weight1=weight1,weight2=weight2,weight3=weight3};}
  [Serializable] class Part{public Bone[] bones;public Vector3[] vertices;public Vector2[] uv;public Weight[] weights;public Section[] submeshes;}
  [Serializable] class Maps{public string albedo,normal,surface,occlusion;public bool specular,cutout;}
  [Serializable] class MaterialEntry{public string name;public Maps unity;}
  [Serializable] class Piece{public string name,path;}
  [Serializable] class Costume{public string name;public string[] pieces;}
  [Serializable] class Manifest{public Costume[] costumes;public Piece[] pieceEntries;public MaterialEntry[] materialEntries;}
  const string Source="Assets/_Project/Characters/Kazuya/Source/Base",Output="Assets/_Project/Characters/Kazuya/Costumes";
  static string Safe(string s)=>new string(s.Select(c=>char.IsLetterOrDigit(c)?c:'_').ToArray());
  static Texture2D Tex(string path,bool normal=false,bool color=false){if(string.IsNullOrEmpty(path))return null;var i=AssetImporter.GetAtPath(path) as TextureImporter;if(!i)throw new Exception("Missing Kazuya texture "+path);i.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;i.sRGBTexture=color;i.maxTextureSize=2048;i.textureCompression=TextureImporterCompression.CompressedHQ;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
  static Material Mat(MaterialEntry e){string path=Output+"/Materials/"+Safe(e.name)+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);var shader=Shader.Find(e.unity.specular?"Standard (Specular setup)":"Standard");if(!m){m=new Material(shader);AssetDatabase.CreateAsset(m,path);}else m.shader=shader;m.color=Color.white;m.SetFloat("_Glossiness",.45f);var a=Tex(e.unity.albedo,false,true);if(a)m.mainTexture=a;var n=Tex(e.unity.normal,true);if(n){m.SetTexture("_BumpMap",n);m.EnableKeyword("_NORMALMAP");}var s=Tex(e.unity.surface);if(s){m.SetTexture(e.unity.specular?"_SpecGlossMap":"_MetallicGlossMap",s);m.EnableKeyword(e.unity.specular?"_SPECGLOSSMAP":"_METALLICGLOSSMAP");}if(e.unity.cutout){m.SetFloat("_Mode",1);m.SetFloat("_Cutoff",.25f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=(int)RenderQueue.AlphaTest;}HdrpProjectSetup.ConvertMaterial(m);if(HdrpProjectSetup.IsEyeShadow(m))HdrpProjectSetup.MakeEyeShadowTransparent(m);EditorUtility.SetDirty(m);return m;}
  static void Add(GameObject root,Transform skeleton,Dictionary<string,Transform> map,Piece entry,Dictionary<string,Material> mats){var p=JsonUtility.FromJson<Part>(File.ReadAllText(entry.path));var bones=new Transform[p.bones.Length];for(int i=0;i<bones.Length;i++){var b=p.bones[i];if(!map.TryGetValue(b.name,out var t)){t=new GameObject(b.name).transform;t.SetParent(b.parent<0?skeleton:bones[b.parent],false);t.localPosition=b.position;t.localRotation=b.rotation;t.localScale=b.scale;map.Add(b.name,t);}bones[i]=t;}var mesh=new Mesh{name=entry.name,indexFormat=IndexFormat.UInt32};mesh.vertices=p.vertices;mesh.uv=p.uv;mesh.boneWeights=p.weights.Select(w=>w.Value).ToArray();var sec=p.submeshes.Where(x=>!x.material.Contains("Eye_ADD")&&x.material!="MI_CH_tear").ToArray();mesh.subMeshCount=sec.Length;var doubled=new Dictionary<int,int[]>();for(int i=0;i<sec.Length;i++){var ids=(int[])sec[i].triangles.Clone();for(int j=0;j<ids.Length;j+=3){int q=ids[j];ids[j]=ids[j+2];ids[j+2]=q;}mesh.SetTriangles(ids,i);if(sec[i].material.Contains("har_")||sec[i].material.Contains("eyelash")){var both=new int[ids.Length*2];Array.Copy(ids,both,ids.Length);for(int j=0;j<ids.Length;j+=3){both[ids.Length+j]=ids[j+2];both[ids.Length+j+1]=ids[j+1];both[ids.Length+j+2]=ids[j];}doubled[i]=both;}}mesh.bindposes=bones.Select(x=>x.worldToLocalMatrix*root.transform.localToWorldMatrix).ToArray();mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();foreach(var pair in doubled)mesh.SetTriangles(pair.Value,pair.Key);string mp=Output+"/Meshes/"+Safe(entry.name)+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(mp);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,mp);var skin=new GameObject(entry.name).AddComponent<SkinnedMeshRenderer>();skin.transform.SetParent(root.transform,false);skin.sharedMesh=mesh;skin.bones=bones;skin.rootBone=map["BASE"];skin.sharedMaterials=sec.Select(x=>mats[x.material]).ToArray();skin.updateWhenOffscreen=true;skin.quality=SkinQuality.Bone4;}
  public static void Import(){Directory.CreateDirectory(Output+"/Materials");Directory.CreateDirectory(Output+"/Meshes");Directory.CreateDirectory(Output+"/Prefabs");AssetDatabase.Refresh();var mf=JsonUtility.FromJson<Manifest>(File.ReadAllText(Source+"/manifest.json"));if(mf.costumes.Length!=8||mf.pieceEntries.Length!=19||mf.materialEntries.Length!=59)throw new Exception("Unexpected Kazuya inventory");var mats=mf.materialEntries.ToDictionary(x=>x.name,Mat);var pieces=mf.pieceEntries.ToDictionary(x=>x.name);foreach(var c in mf.costumes){var root=new GameObject("Kazuya Mishima - "+c.name);var sk=new GameObject("Skeleton").transform;sk.SetParent(root.transform,false);var bones=new Dictionary<string,Transform>(StringComparer.OrdinalIgnoreCase);foreach(var name in c.pieces)Add(root,sk,bones,pieces[name],mats);PrefabUtility.SaveAsPrefabAsset(root,Output+"/Prefabs/"+Safe(c.name)+".prefab");UnityEngine.Object.DestroyImmediate(root);}AssetDatabase.SaveAssets();File.WriteAllText("Validation/kazuya-model.json","{\"passed\":true,\"costumes\":8,\"pieces\":19,\"materials\":59,\"caseInsensitiveBones\":true}");}
  public static MuseumCharacter.Costume[] LoadCostumes(){var mf=JsonUtility.FromJson<Manifest>(File.ReadAllText(Source+"/manifest.json"));return mf.costumes.Select(c=>new MuseumCharacter.Costume{name=c.name,prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Output+"/Prefabs/"+Safe(c.name)+".prefab")}).ToArray();}
 }
}
